import React , { useState }from "react";
import "./Head2.css";
import ScrollProgressBar from "../../../componant/ScrollProgressBar";
import { useNavigate } from 'react-router-dom';
import axios from "axios";

const Head = () => {
    const [isAuthenticated, setIsAuthenticated] = useState(false);
  
  const navigate = useNavigate();
  const  ProfileCard = () => {
    navigate('/ProfileCard');
  };
  const  signup = () => {
    navigate('/Signup');
  };


    const handleLogout = async () => {
    const token = localStorage.getItem("authToken");
    if (!token) return;

    try {
      await axios.post(`${process.env.REACT_APP_API_BASE_URL}/logout`, {}, {
        headers: { Authorization: `Bearer ${token}` },
      });

      localStorage.clear();
      setIsAuthenticated(false);
      navigate("/");
    } catch (error) {
      navigate("/login");
    }
  };
  return (
    <>
      <section className="head">
        <div className="container flexSB">
          {/* ✅ الصورة على اليسار */}
          <div className="left-logo">
            <img src="/images/logo.jpg" alt="Logo" className="logo-img" />
          </div>

          {/* ✅ الاسم في المنتصف */}
        
          {/* ✅ الأزرار في اليمين */}
          <div className="buttons">
            <button onClick={ handleLogout} className="btn signup">تسجيل الخروج</button>
            <button onClick={ProfileCard} className="btn login">المحاضرات</button>
          </div>
        </div>
      </section>
      <ScrollProgressBar />
    </>
  );
};

export default Head;
